INSERT OR IGNORE INTO open_questions (id, question, evidence, action_summary, proposal_json, status, created_at) VALUES ('oq-fatemeh-massoudi-sister', 'Is Fatemeh Massoudi — Seifollah Jaberian''s wife — the same Fatemeh who was Robabeh Masoudi''s sister?', 'The family biography''s account of Ghassem Darabi names Robabeh''s brothers and sisters: Ebrahim, Esmail, Mahmoud, Fatemeh and Masoumeh. A Fatemeh Massoudi is recorded as Seifollah Jaberian''s wife, but no document states she is that sister.', 'If confirmed, Fatemeh Massoudi is linked as a daughter of Haj Mirza Agha Masoudi and her record notes she was Robabeh''s sister.', '{"actions":[{"type":"add_parent","parentId":"b9a60325-2ac4-4f02-ab3b-05e4a182195f","childId":"98231253-1443-4cb2-9605-7ea614213b02"},{"type":"append_biography","personId":"98231253-1443-4cb2-9605-7ea614213b02","text":"Daughter of Haj Mirza Agha Masoudi and sister of Robabeh Masoudi."}]}', 'open', '2026-08-27T09:04:13.261Z');
INSERT OR IGNORE INTO open_questions (id, question, evidence, action_summary, proposal_json, status, created_at) VALUES ('oq-mohammad-zehtab-second-wife', 'What was the name of Mohammad Zehtab Darabi''s second wife?', 'The family biography records that after Salmeh died in middle age, Mohammad''s children chose a second wife for him, and that she remained at his side to the end of his life — but it never gives her name.', 'Enter her name to add her to the tree as Mohammad Zehtab Darabi''s wife.', '{"actions":[{"type":"create_spouse","ofId":"c8a1f8a4-d83d-4638-8de4-ceb8246908cb","gender":"female","nameFromAnswer":true,"biography":"Second wife of Mohammad Zehtab Darabi, chosen for him by his children after Salmeh died in middle age. The family biography records that she remained at his side to the end of his life."}]}', 'open', '2026-08-27T09:04:13.261Z');
INSERT OR IGNORE INTO open_questions (id, question, evidence, action_summary, proposal_json, status, created_at) VALUES ('oq-ashraf-bookkeeper-daughter', 'Was Ashraf Nokhodberizan the bookkeeper''s daughter of the double wedding of about 1927?', 'The history “A historic marriage” records that Asadollah Jaberian married the daughter of the partnership''s bookkeeper — a respected Qazvin merchant who had lost his fortune — in a match arranged the same evening. Asadollah''s recorded wife is Ashraf Nokhodberizan, but the story never names the bride.', 'If confirmed, Ashraf''s record notes that her father was the partnership''s bookkeeper of the marriage story.', '{"actions":[{"type":"append_biography","personId":"7e700bb4-7bd2-4fb9-96b5-201cd9a7c5e0","text":"Her father was a respected Qazvin merchant who, after losing his fortune, joined the family partnership as its bookkeeper; the double wedding of about 1927 in the family history is hers and Asadollah''s."}]}', 'open', '2026-08-27T09:04:13.261Z');
INSERT OR IGNORE INTO open_questions (id, question, evidence, action_summary, proposal_json, status, created_at) VALUES ('oq-1920-photo-figures', 'Who are the two unidentified men in the 1920 photograph (fourth and sixth from the left)?', 'The family biography''s caption for the earliest photograph reads: “Left to right: Abbas Darabi, Hossein Zehtab Darabi, Asadollah Jaberian, -?, Ghassem Darabi, -?. Picture; approximately 1920.” Figures 4 and 6 were never identified.', 'Write what you know in the note — an editor will add them to the photograph''s records.', NULL, 'open', '2026-08-27T09:04:13.261Z');
INSERT INTO change_log (id, actor_email, kind, summary, payload_json, created_at) VALUES ('6a42dce3-4c8b-4f13-99c4-cdf4febafe12', 'ramine@ramine.net', 'seed_open_questions', 'Queued 4 open questions from the family histories for review in the Fill-in tab.', '{"questions":["Is Fatemeh Massoudi — Seifollah Jaberian''s wife — the same Fatemeh who was Robabeh Masoudi''s sister?","What was the name of Mohammad Zehtab Darabi''s second wife?","Was Ashraf Nokhodberizan the bookkeeper''s daughter of the double wedding of about 1927?","Who are the two unidentified men in the 1920 photograph (fourth and sixth from the left)?"]}', '2026-08-27T09:04:13.261Z');
